// ============================================================================
// AES_GCM_apb: APB4 register wrapper around AES_GCM_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/AES_GCM.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/AES_GCM.md
// ============================================================================
module AES_GCM_apb #(
  parameter int LEN_W = 36
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [255:0] sl_key,
  input logic sl_valid
);
  localparam logic [31:0] ID_VALUE = 32'h41470100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [36:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd37) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_key256;
  logic          c_decrypt;
  logic          c_key_sel;
  logic [3:0]    c_tag_len;
  logic [255:0]  c_key;
  logic [95:0]   c_iv;
  logic [127:0]  c_tag_in;
  logic          c_start;
  logic          c_clr;
  logic          c_busy;
  logic          c_in_valid;
  logic          c_in_ready;
  logic [127:0]  c_in_data;
  logic [4:0]    c_in_bytes;
  logic          c_in_aad;
  logic          c_in_last;
  logic          c_out_valid;
  logic          c_out_ready;
  logic [127:0]  c_out_data;
  logic [4:0]    c_out_bytes;
  logic          c_out_last;
  logic          c_done;
  logic [127:0]  c_tag;
  logic          c_tag_ok;
  logic          c_err;
  logic [2:0]    c_err_code;
  AES_GCM_top #(.LEN_W(LEN_W)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .key256(c_key256),
    .decrypt(c_decrypt),
    .key_sel(c_key_sel),
    .tag_len(c_tag_len),
    .key(c_key),
    .iv(c_iv),
    .tag_in(c_tag_in),
    .sl_key(sl_key),
    .sl_valid(sl_valid),
    .start(c_start),
    .clr(c_clr),
    .busy(c_busy),
    .in_valid(c_in_valid),
    .in_ready(c_in_ready),
    .in_data(c_in_data),
    .in_bytes(c_in_bytes),
    .in_aad(c_in_aad),
    .in_last(c_in_last),
    .out_valid(c_out_valid),
    .out_ready(c_out_ready),
    .out_data(c_out_data),
    .out_bytes(c_out_bytes),
    .out_last(c_out_last),
    .done(c_done),
    .tag(c_tag),
    .tag_ok(c_tag_ok),
    .err(c_err),
    .err_code(c_err_code)
  );

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [6:0] r_CTRL;   // 12'h014 CTRL
  logic [31:0] r_KEY0;   // 12'h018 KEY0
  logic [31:0] r_KEY1;   // 12'h01C KEY1
  logic [31:0] r_KEY2;   // 12'h020 KEY2
  logic [31:0] r_KEY3;   // 12'h024 KEY3
  logic [31:0] r_KEY4;   // 12'h028 KEY4
  logic [31:0] r_KEY5;   // 12'h02C KEY5
  logic [31:0] r_KEY6;   // 12'h030 KEY6
  logic [31:0] r_KEY7;   // 12'h034 KEY7
  logic [31:0] r_IV0;   // 12'h038 IV0
  logic [31:0] r_IV1;   // 12'h03C IV1
  logic [31:0] r_IV2;   // 12'h040 IV2
  logic [31:0] r_TAG_IN0;   // 12'h044 TAG_IN0
  logic [31:0] r_TAG_IN1;   // 12'h048 TAG_IN1
  logic [31:0] r_TAG_IN2;   // 12'h04C TAG_IN2
  logic [31:0] r_TAG_IN3;   // 12'h050 TAG_IN3
  logic [1:0] p_CMD;   // 12'h054 CMD (pulses)
  logic [31:0] h_IN0;   // 12'h058 IN0 holding register
  logic [31:0] h_IN1;   // 12'h05C IN1 holding register
  logic [31:0] h_IN2;   // 12'h060 IN2 holding register
  logic [31:0] h_IN3;   // 12'h064 IN3 holding register
  logic [6:0] h_IN4;   // 12'h068 IN4 holding register
  logic [31:0] h_OUT0;   // 12'h06C OUT0 holding register
  logic [31:0] h_OUT1;   // 12'h070 OUT1 holding register
  logic [31:0] h_OUT2;   // 12'h074 OUT2 holding register
  logic [31:0] h_OUT3;   // 12'h078 OUT3 holding register
  logic [5:0] h_OUT4;   // 12'h07C OUT4 holding register
  logic full_IN;
  logic avail_OUT;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 7'h0;
      r_KEY0 <= 32'h0;
      r_KEY1 <= 32'h0;
      r_KEY2 <= 32'h0;
      r_KEY3 <= 32'h0;
      r_KEY4 <= 32'h0;
      r_KEY5 <= 32'h0;
      r_KEY6 <= 32'h0;
      r_KEY7 <= 32'h0;
      r_IV0 <= 32'h0;
      r_IV1 <= 32'h0;
      r_IV2 <= 32'h0;
      r_TAG_IN0 <= 32'h0;
      r_TAG_IN1 <= 32'h0;
      r_TAG_IN2 <= 32'h0;
      r_TAG_IN3 <= 32'h0;
      p_CMD <= '0;
      h_IN0 <= '0;
      h_IN1 <= '0;
      h_IN2 <= '0;
      h_IN3 <= '0;
      h_IN4 <= '0;
      h_OUT0 <= '0;
      h_OUT1 <= '0;
      h_OUT2 <= '0;
      h_OUT3 <= '0;
      h_OUT4 <= '0;
      full_IN <= 1'b0;
      avail_OUT <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[6]) r_KEY0 <= (r_KEY0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_KEY1 <= (r_KEY1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_KEY2 <= (r_KEY2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_KEY3 <= (r_KEY3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_KEY4 <= (r_KEY4 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[11]) r_KEY5 <= (r_KEY5 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[12]) r_KEY6 <= (r_KEY6 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) r_KEY7 <= (r_KEY7 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[14]) r_IV0 <= (r_IV0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[15]) r_IV1 <= (r_IV1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[16]) r_IV2 <= (r_IV2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[17]) r_TAG_IN0 <= (r_TAG_IN0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[18]) r_TAG_IN1 <= (r_TAG_IN1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[19]) r_TAG_IN2 <= (r_TAG_IN2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[20]) r_TAG_IN3 <= (r_TAG_IN3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_CMD <= (wr && hit[21]) ? PWDATA[1:0] & wmask[1:0] : '0;
      if (wr && hit[22] && !full_IN) h_IN0 <= (h_IN0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[23] && !full_IN) h_IN1 <= (h_IN1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[24] && !full_IN) h_IN2 <= (h_IN2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[25] && !full_IN) h_IN3 <= (h_IN3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[26] && !full_IN) h_IN4 <= (h_IN4 & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[26] && !full_IN) full_IN <= 1'b1;
      else if (full_IN && c_in_ready) full_IN <= 1'b0;
      if (c_out_valid && (!avail_OUT || (rd && hit[31]))) begin
        h_OUT0[31:0] <= c_out_data[31:0];
        h_OUT1[31:0] <= c_out_data[63:32];
        h_OUT2[31:0] <= c_out_data[95:64];
        h_OUT3[31:0] <= c_out_data[127:96];
        h_OUT4[4:0] <= c_out_bytes[4:0];
        h_OUT4[5:5] <= c_out_last;
        avail_OUT <= 1'b1;
      end else if (rd && hit[31]) avail_OUT <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_key256 = r_CTRL[0:0];
  assign c_decrypt = r_CTRL[1:1];
  assign c_key_sel = r_CTRL[2:2];
  assign c_tag_len = r_CTRL[6:3];
  assign c_key[31:0] = r_KEY0[31:0];
  assign c_key[63:32] = r_KEY1[31:0];
  assign c_key[95:64] = r_KEY2[31:0];
  assign c_key[127:96] = r_KEY3[31:0];
  assign c_key[159:128] = r_KEY4[31:0];
  assign c_key[191:160] = r_KEY5[31:0];
  assign c_key[223:192] = r_KEY6[31:0];
  assign c_key[255:224] = r_KEY7[31:0];
  assign c_iv[31:0] = r_IV0[31:0];
  assign c_iv[63:32] = r_IV1[31:0];
  assign c_iv[95:64] = r_IV2[31:0];
  assign c_tag_in[31:0] = r_TAG_IN0[31:0];
  assign c_tag_in[63:32] = r_TAG_IN1[31:0];
  assign c_tag_in[95:64] = r_TAG_IN2[31:0];
  assign c_tag_in[127:96] = r_TAG_IN3[31:0];
  assign c_start = p_CMD[0:0];
  assign c_clr = p_CMD[1:1];
  assign c_in_data[31:0] = h_IN0[31:0];
  assign c_in_data[63:32] = h_IN1[31:0];
  assign c_in_data[95:64] = h_IN2[31:0];
  assign c_in_data[127:96] = h_IN3[31:0];
  assign c_in_bytes[4:0] = h_IN4[4:0];
  assign c_in_aad = h_IN4[5:5];
  assign c_in_last = h_IN4[6:6];
  assign c_in_valid = full_IN;
  assign c_out_ready = ~avail_OUT | (rd & hit[31]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_err;
    irq_set[2] = full_IN & c_in_ready;
    irq_set[3] = wr & (hit[22] | hit[23] | hit[24] | hit[25] | hit[26]) & full_IN;
    irq_set[4] = c_out_valid & (~avail_OUT | (rd & hit[31]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_OUT, full_IN};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd14: apb_rdata = 32'(r_IV0);
      10'd15: apb_rdata = 32'(r_IV1);
      10'd16: apb_rdata = 32'(r_IV2);
      10'd17: apb_rdata = 32'(r_TAG_IN0);
      10'd18: apb_rdata = 32'(r_TAG_IN1);
      10'd19: apb_rdata = 32'(r_TAG_IN2);
      10'd20: apb_rdata = 32'(r_TAG_IN3);
      10'd22: apb_rdata = 32'(h_IN0);
      10'd23: apb_rdata = 32'(h_IN1);
      10'd24: apb_rdata = 32'(h_IN2);
      10'd25: apb_rdata = 32'(h_IN3);
      10'd26: apb_rdata = 32'(h_IN4);
      10'd27: apb_rdata = 32'(h_OUT0);
      10'd28: apb_rdata = 32'(h_OUT1);
      10'd29: apb_rdata = 32'(h_OUT2);
      10'd30: apb_rdata = 32'(h_OUT3);
      10'd31: apb_rdata = 32'(h_OUT4);
      10'd32: apb_rdata = 32'({c_tag[31:0]});
      10'd33: apb_rdata = 32'({c_tag[63:32]});
      10'd34: apb_rdata = 32'({c_tag[95:64]});
      10'd35: apb_rdata = 32'({c_tag[127:96]});
      10'd36: apb_rdata = 32'({c_err_code, c_tag_ok, c_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
